# For Linux (optional, uncomment if on Linux):
# x11-clipboard = "0.7"
# For macOS (optional, uncomment if on macOS):
# macos-clipboard = "0.1"

# Audio playback
# We will use a simple approach: download audio to a temp file and play it.
# For a robust cross-platform solution, you might need 'rodio' or 'cpal', 
