Here are the two functions to pack and unpack the data.

### The Logic
Since the total size of an entity is 7 bits ($4 + 3$), we cannot use standard 8-bit integers (`Uint8`) directly without wasting space. We must use a `Uint8Array` and manually shift bits.

*   **Packing:** We iterate through the entities. For each entity, we take the `id` (4 bits) and `size` (3 bits), combine them into a 7-bit integer, and write that integer into the buffer.
*   **Unpacking:** We iterate through the buffer. We read 7 bits at a time. The top 4 bits are the `id`, and the bottom 3 bits are the `size`.

### JavaScript Code

```javascript
/**
 * Packs an array of entities into a Uint8Array.
 * 
 * @param {Array} entities - Array of objects with { id: number, size: number }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
    if (!entities || entities.length === 0) {
        return new Uint8Array(0);
    }

    // Calculate total size: 7 bits per entity
    // 7 bits = ceil(7/8) = 1 byte per entity
    const totalBytes = entities.length;
    const buffer = new Uint8Array(totalBytes);

    for (let i = 0; i < entities.length; i++) {
        const { id, size } = entities[i];

        // Combine id (4 bits) and size (3 bits) into a 7-bit integer
        // (id << 3) moves id to the top 4 bits
        // size occupies the bottom 3 bits
        const packedValue = (id << 3) | size;

        // Write the 7-bit value into the buffer
        // Since 7 bits < 8 bits, it fits perfectly into one byte
        buffer[i] = packedValue;
    }

    return buffer;
}

/**
 * Unpacks a Uint8Array into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id: number, size: number }
 */
function unpackEntities(buffer) {
    const entities = [];

    for (let i = 0; i < buffer.length; i++) {
        const byte = buffer[i];

        // Extract id (top 4 bits)
        // (byte >> 3) shifts the 7-bit value right by 3 positions
        const id = byte >> 3;

        // Extract size (bottom 3 bits)
        // (byte & 0x07) masks out the top 4 bits, keeping only the bottom 3
        const size = byte & 0x07;

        entities.push({ id, size });
    }

    return entities;
}

// --- Example Usage ---

