### 1. The Web Worker (`worker.js`)

First, we create the worker file. This file contains the logic to parse the CSV. It runs in a separate thread.

**File:** `src/worker/parse-csv-worker.js`

```javascript
import { parse } from 'csv-parse/sync';

// We use a simple self-posting pattern to communicate back to the main thread
self.onmessage = (event) => {
  const { fileContent, delimiter } = event.data;

  try {
    const records = parse(fileContent, {
      delimiter: delimiter || ',',
      skip_empty_lines: true,
      trim: true,
      columns: true, // Returns an object per row
      relax_column_count: true,
    });

    // Send the result back to the main thread
    self.postMessage({
      type: 'success',
      data: records,
    });
  } catch (error) {
    self.postMessage({
      type: 'error',
      message: error.message,
    });
  }
};
```

