    // Pseudo-code for a Voronoi-style cellular blend
    vec3 gridPos = floor(p * gridScale);
    float cellNoise = cnoise(gridPos * cellSeed);
    float threshold = 0.5;

    // If cell is "A", use d1; if "B", use d2
    float d1 = (cellNoise < threshold) ? shapeA(p) : 0.0;
    float d2 = (cellNoise >= threshold) ? shapeB(p) : 0.0;

    // Combine them (Union)
    return min(d1, d2); 
